#include <iostream>
#include <string>

int findWord(const std::string& text, const std::string& word) {
    // size() is unsigned, so text.size() - word.size() would wrap around
    // when the word is longer. Plain ints avoid that.
    int n = static_cast<int>(text.size());
    int m = static_cast<int>(word.size());
    for (int start = 0; start + m <= n; start++) {
        int i = 0;
        while (i < m && text[start + i] == word[i]) {
            i++;
        }
        if (i == m) {
            return start;
        }
    }
    return -1;
}

int main() {
    std::string text, word;
    std::getline(std::cin, text);
    std::getline(std::cin, word);
    std::cout << findWord(text, word) << "\n";
    return 0;
}

