import java.util.Scanner;

public class Main {
    static int findWord(String text, String word) {
        for (int start = 0; start + word.length() <= text.length(); start++) {
            int i = 0;
            while (i < word.length() && text.charAt(start + i) == word.charAt(i)) {
                i++;
            }
            if (i == word.length()) {
                return start;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String text = in.nextLine();
        String word = in.nextLine();
        System.out.println(findWord(text, word));
    }
}

