import (
	"bufio"
	"fmt"
	"os"
)

func findWord(text, word string) int {
	n, m := len(text), len(word)
	for start := 0; start+m <= n; start++ {
		i := 0
		for i < m && text[start+i] == word[i] {
			i++
		}
		if i == m {
			return start
		}
	}
	return -1
}

